# j. maurice rojas, sep. 22, 2016
# this short program picks a random a in {1,...,n-1} 
# and checks if it is a miller-rabin witness. this 
# code is far from optimal and is meant more to 
# familiarize the reader with maple syntax than to 
# be elegant.  : ) 

#  n := 127536587059848552564790095500160708695457833641416263171762398330267983365550211308910941805461159945947024273103825623764236065204421727414482691703159412729513690774618306375341 :  

# n:=172947529:  # 17 fails...

 n :=  643808006803554439230129854961492699151386107534013432918073439524138264842370630061369715394739134090922937332590384720397133335969549256322620979036686633213903952966175107096769180017646161851573147596390153:

with(numtheory): with(padic): 

randoma:=rand(1..(n-1)): 
ord2:=ordp(n-1,2):  
q:=(n-1)/2^ord2: 

a:=randoma(): [n,ord2,a]; 
# when n=172947529, try # a:=17: [n,ord2,a];
a:=Power(a,q) mod n: 
w:=[a]: len:=1: fail:=0: 

if (a<>1 mod n) then 
 for i from 0 to (ord2-1) do 
  if (a<>-1 mod n) then  
   a:=a^2 mod n: 
   w:=[seq(w[i],i=1..len),a]: len:=len+1: 
  elif (a=-1 mod n) and (fail=0) then 
   print("a is not a witness"): fail:=1: 
  end: 
 end: 
elif (a=1 mod n) then 
 print("a is not a witness..."): fail:=1: 
end if: 

if fail=0 then 
 print("Here is your witness!:"): 
 print([len,w]): 
end: 

